import { Node } from "./Node";
/**
 * @description テクスチャパッカー
 *              Texture packer
 *
 * @class
 * @public
 */
export class TexturePacker {
    /**
     * @param {number} index
     * @param {number} width
     * @param {number} height
     * @constructor
     * @public
     */
    constructor(index, width, height) {
        /**
         * @description ルートノード
         *              Root node
         *
         * @type {Node}
         * @private
         */
        Object.defineProperty(this, "_$root", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        this._$root = new Node(index, 0, 0, width, height);
    }
    /**
     * @description テクスチャをパック、挿入したノードを返却します。
     *              Pack the texture and return the inserted node.
     *
     * @param  {number} width
     * @param  {number} height
     * @return {Node | null}
     * @method
     * @public
     */
    insert(width, height) {
        return this._$root.insert(width, height);
    }
    /**
     * @description Nodeを破棄します。
     *              Dispose of the Node.
     *
     * @param  {number} x
     * @param  {number} y
     * @param  {number} width
     * @param  {number} height
     * @return {boolean}
     * @method
     * @public
     */
    dispose(x, y, width, height) {
        return this._$root.dispose(x, y, width, height);
    }
}
